SKILL_BUNDLE:
{
  "task_skill": {
    "title": "Find Statue, Carry to Sidetable",
    "principle": "Search likely storage surfaces for a statue, pick up any available statue, navigate to the sidetable, and place the statue on it.",
    "when_to_apply": "Use when the task requires putting a statue on a sidetable or moving a named pickup object to a specified receptacle."
  },
  "step_skills": [
    {
      "source_trajectory_index": 1,
      "source_turn": 1,
      "title": "Identify Search Locations and Target Receptacle",
      "principle": "From the room overview, note that the sidetable is the destination and shelves are plausible places to search for small decorative objects like statues.",
      "when_to_apply": "At the start of the task when the room contains shelves and a sidetable but the statue is not immediately visible."
    },
    {
      "source_trajectory_index": 1,
      "source_turn": 2,
      "title": "Continue Searching When First Surface Lacks Statue",
      "principle": "If a searched shelf contains other objects but no statue, do not stop there; move to another visible shelf or storage surface to continue looking.",
      "when_to_apply": "When observing a shelf with items such as newspaper, vase, or wateringcan but no statue."
    },
    {
      "source_trajectory_index": 1,
      "source_turn": 3,
      "title": "Select an Available Statue",
      "principle": "When a shelf contains one or more statues, choose any statue as the required object for the task.",
      "when_to_apply": "When observing a shelf that lists statues among its contents."
    },
    {
      "source_trajectory_index": 1,
      "source_turn": 4,
      "title": "Carry the Statue to the Destination",
      "principle": "After picking up the statue, navigate directly to the sidetable because it is the required placement location.",
      "when_to_apply": "Immediately after successfully picking up a statue."
    },
    {
      "source_trajectory_index": 1,
      "source_turn": 5,
      "title": "Place Statue on Empty Sidetable",
      "principle": "Once at the sidetable while carrying the statue, put the statue on the sidetable to complete the task.",
      "when_to_apply": "When standing at the sidetable after collecting a statue, especially if the sidetable is empty."
    }
  ]
}

